import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { toIsoTimestamp } from "@/types/common";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let ent: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  ent = await createTenant("scratchent", "enterprise");
  growth = await createTenant("scratchgrowth", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

const all = ["issue", "comment", "project"] as const;

describe("scratch", () => {
  it("symptom 1: colon title on Starter-like (growth) finds the issue", async () => {
    await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "Release 2: hotfix" }),
    );
    const hits = await searchService.search(growth.actors.member, {
      orgId: growth.org.id,
      q: "Release 2: hotfix",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.total).toBe(1);
  });

  it("symptom 2 + 3: kind:comment and project-scoped comment search on enterprise", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "Flaky host" }),
    );
    await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "this test is flaky on CI",
      parentId: null,
      mentionedUserIds: [],
    });
    const kindHits = await searchService.search(ent.actors.member, {
      orgId: ent.org.id,
      q: "kind:comment flaky",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(kindHits.total).toBe(1);
    expect(kindHits.items[0]?.kind).toBe("comment");

    const inHits = await searchService.search(ent.actors.member, {
      orgId: ent.org.id,
      q: "in:comments flaky",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(inHits.total).toBe(1);

    const projHits = await searchService.search(ent.actors.member, {
      orgId: ent.org.id,
      q: `project:${ent.project.id} flaky`,
      kinds: all.slice(),
      limit: 25,
      cursor: null,
    });
    expect(projHits.items.map((h) => h.kind)).toContain("comment");

    const scoped = await searchService.search(ent.actors.member, {
      orgId: ent.org.id,
      q: "flaky",
      kinds: all.slice(),
      projectId: ent.project.id,
      limit: 25,
      cursor: null,
    });
    expect(scoped.items.map((h) => h.kind)).toContain("comment");
  });

  it("symptom 4: literal % and _", async () => {
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake case words" }),
    );
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "snake_case words" }),
    );
    const under = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: "snake_case", kinds: ["issue"], limit: 25, cursor: null,
    });
    expect(under.total).toBe(1);
    const pct = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: "100%", kinds: ["issue"], limit: 25, cursor: null,
    });
    expect(pct.total).toBe(0);
  });

  it("symptom 5: growth palette asks for all kinds, only issues come back", async () => {
    const issue = await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "Growth palette issue" }),
    );
    await commentService.createComment(growth.actors.member, {
      orgId: growth.org.id,
      issueId: issue.id,
      body: "growth palette comment",
      parentId: null,
      mentionedUserIds: [],
    });
    const hits = await searchService.search(growth.actors.member, {
      orgId: growth.org.id, q: "growth palette", kinds: all.slice(), limit: 25, cursor: null,
    });
    expect(hits.items.every((h) => h.kind === "issue")).toBe(true);
  });

  it("symptom 6: reindex of comment, project and archived issue", async () => {
    const issue = await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, ent.project.id, { title: "ReindexArchivedMarker" }),
    );
    const comment = await commentService.createComment(ent.actors.member, {
      orgId: ent.org.id,
      issueId: issue.id,
      body: "ReindexCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    const at = toIsoTimestamp(new Date());
    // Remove the comment doc, then reindex it.
    await emit("comment.deleted", {
      orgId: ent.org.id, actorId: null, occurredAt: at,
      commentId: comment.id, issueId: issue.id,
    });
    await emit("search.reindex_requested", {
      orgId: ent.org.id, actorId: null, occurredAt: at,
      subjectKind: "comment", subjectId: comment.id,
    });
    const c = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: "ReindexCommentMarker", kinds: ["comment"], limit: 25, cursor: null,
    });
    // comment.deleted archived it, so reindex must NOT resurrect it
    expect(c.total).toBe(0);

    await emit("search.reindex_requested", {
      orgId: ent.org.id, actorId: null, occurredAt: at,
      subjectKind: "project", subjectId: ent.project.id,
    });
    const p = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: ent.project.name, kinds: ["project"], limit: 25, cursor: null,
    });
    expect(p.total).toBeGreaterThanOrEqual(1);

    await issueService.archiveIssue(ent.actors.member, ent.org.id, issue.id);
    await emit("search.reindex_requested", {
      orgId: ent.org.id, actorId: null, occurredAt: at,
      subjectKind: "issue", subjectId: issue.id,
    });
    const i = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: "ReindexArchivedMarker", kinds: ["issue"], limit: 25, cursor: null,
    });
    expect(i.total).toBe(0);
  });

  it("project restore re-indexes the project; archive drops its issues", async () => {
    const proj = await projectService.createProject(ent.actors.owner ?? ent.actors.member, {
      orgId: ent.org.id, name: "ScratchRestoreProj", slug: "scratch-restore-proj", description: null,
    } as never);
    await issueService.createIssue(
      ent.actors.member,
      issueInput(ent.org.id, proj.id, { title: "ProjCascadeMarker" }),
    );
    const before = await searchService.search(ent.actors.member, {
      orgId: ent.org.id, q: "ProjCascadeMarker", kinds: ["issue"], limit: 25, cursor: null,
    });
    expect(before.total).toBe(1);
  });
});
